using System.Collections; using UnityEngine;
public class SuccessfulHitRedFlash:MonoBehaviour { [SerializeField] private Renderer[] targetRenderers; [SerializeField] private Color hitColor=Color.red; [SerializeField,Min(.05f)] private float duration=.2f; private Color[][] original; private Coroutine routine;
 private void Awake(){if(targetRenderers==null||targetRenderers.Length==0)targetRenderers=GetComponentsInChildren<Renderer>(true);original=new Color[targetRenderers.Length][];for(int i=0;i<targetRenderers.Length;i++){if(targetRenderers[i]==null)continue;Material[] m=targetRenderers[i].materials;original[i]=new Color[m.Length];for(int j=0;j<m.Length;j++)original[i][j]=m[j].HasProperty("_Color")?m[j].color:Color.white;}}
 public void HighlightSuccessfulHit(){if(routine!=null)StopCoroutine(routine);routine=StartCoroutine(Flash());} private IEnumerator Flash(){Set(hitColor);yield return new WaitForSecondsRealtime(duration);Restore();routine=null;} private void Set(Color c){foreach(Renderer r in targetRenderers)if(r!=null)foreach(Material m in r.materials)if(m.HasProperty("_Color"))m.color=c;} private void Restore(){for(int i=0;i<targetRenderers.Length;i++){if(targetRenderers[i]==null||original[i]==null)continue;Material[] m=targetRenderers[i].materials;for(int j=0;j<m.Length&&j<original[i].Length;j++)if(m[j].HasProperty("_Color"))m[j].color=original[i][j];}} }
